export default function f({ uid, actualUid, subject, attachments }) {
  if (uid !== actualUid) throw Error("Message mismatch");
  const text = typeof subject === "string" ? subject : "";
  const match = /(expenses|reciept|receipt)/i.test(text);
  if (!match) return { match: false, attachmentId: "unused", subject: text };
  const first = attachments?.[0]?.attachmentId;
  if (typeof first !== "string" || !first) throw Error("Matching email has no first attachment");
  return { match: true, attachmentId: first, subject: text };
}

