export default async function f(
  { uid, url, modelId, acknowledge, resolution, confirmedJobId },
  ctx,
) {
  const key = "receipt-email:job:" + uid,
    old = await ctx.state.get(key);
  if (old?.status === "ready") return { key, send: false, jobId: old.jobId, body: "" };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending Mindee job " + key);
    if (resolution === "confirmed") {
      if (!/^[0-9a-f-]{36}$/i.test(confirmedJobId)) throw Error("Confirmed job ID required");
      await ctx.state.set(key, { status: "ready", jobId: confirmedJobId });
      return { key, send: false, jobId: confirmedJobId, body: "" };
    }
  }
  if (!/^https:\/\//.test(url) || !/^[0-9a-f-]{36}$/i.test(modelId))
    throw Error("Configure Mindee");
  const boundary = "openflow-mindee-form-7d1b8e6f";
  if (url.includes(boundary)) throw Error("Invalid attachment URL");
  const body = `--${boundary}\r\nContent-Disposition: form-data; name="model_id"\r\n\r\n${modelId}\r\n--${boundary}\r\nContent-Disposition: form-data; name="url"\r\n\r\n${url}\r\n--${boundary}--\r\n`;
  await ctx.state.set(key, { status: "pending" });
  return { key, send: true, jobId: "", body };
}

