export default async function f({ body, statusCode, key, modelId }, ctx) {
  const id = body?.job?.id;
  if (statusCode !== 202 || !/^[0-9a-f-]{36}$/i.test(id || "") || body.job.model_id !== modelId)
    throw Error("Unknown Mindee job");
  await ctx.state.set(key, { status: "ready", jobId: id });
  return { jobId: id };
}

