function status({ body, jobId, previousState }) {
  const attempt = (previousState?.attempt ?? 0) + 1,
    j = body?.job;
  if (!Number.isInteger(attempt) || attempt > 200 || j?.id !== jobId)
    throw Error("Invalid Mindee job status");
  if (j.status === "Failed") throw Error("Mindee receipt processing failed");
  if (j.status === "Processing") {
    if (attempt >= 200) throw Error("Mindee did not finish within the polling window");
    return {
      state: { attempt },
      ready: false,
      resultUrl: "https://api-v2.mindee.net/v2/products/extraction/results/unused",
    };
  }
  if (
    j.status !== "Processed" ||
    !/^https:\/\/api-v2\.mindee\.net\/v2\/products\/extraction\/results\/[0-9a-f-]{36}$/i.test(
      j.result_url ?? "",
    )
  )
    throw Error("Invalid Mindee result URL");
  return { state: { attempt }, ready: true, resultUrl: j.result_url };
}

export default function f(input) {
  if (input.statusCode < 200 || input.statusCode >= 300) throw Error("Mindee status unavailable");
  return status(input);
}

