export default async function f(
  { uid, subject, data, statusCode, jobId, spreadsheetId, acknowledge, resolution },
  ctx,
) {
  const fields = data?.inference?.result?.fields;
  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    data?.inference?.job?.id !== jobId ||
    !fields ||
    typeof fields !== "object"
  )
    throw Error("Wrong Mindee result");
  const get = (f) => f?.value ?? "",
    amount = get(fields.total_amount),
    date = get(fields.date),
    category = get(fields.purchase_category),
    currency = get(fields.locale?.fields?.currency);
  if (amount !== "" && (typeof amount !== "number" || !Number.isFinite(amount)))
    throw Error("Invalid receipt total");
  for (const x of [date, category, currency])
    if (typeof x !== "string") throw Error("Invalid receipt field");
  const key = "receipt-email:sheet:" + uid,
    old = await ctx.state.get(key);
  if (old?.status === "done")
    return { key, write: false, spreadsheetId, range: "Receipts!A:E", values: [] };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending receipt row " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { key, write: false, spreadsheetId, range: "Receipts!A:E", values: [] };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return {
    key,
    write: true,
    spreadsheetId,
    range: "Receipts!A:E",
    values: [[date, subject.split("-")[1] || "", category, currency, amount]],
  };
}

