export default async function f({ uid, acknowledge, resolution }, ctx) {
  const key = "receipt-email:read:" + uid,
    old = await ctx.state.get(key);
  if (old?.status === "done") return { key, mark: false };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending read flag " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { key, mark: false };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { key, mark: true };
}

